!function(e){function t(t){for(var a,i,p=t[0],d=t[1],m=t[2],s=0,f=[];s<p.length;s++)i=p[s],Object.prototype.hasOwnProperty.call(n,i)&&n[i]&&f.push(n[i][0]),n[i]=0;for(a in d)Object.prototype.hasOwnProperty.call(d,a)&&(e[a]=d[a]);for(c&&c(t);f.length;)f.shift()();return o.push.apply(o,m||[]),r()}function r(){for(var e,t=0;t<o.length;t++){for(var r,i=o[t],p=!0,d=1;d<i.length;d++)r=i[d],0!==n[r]&&(p=!1);p&&(o.splice(t--,1),e=a(a.s=i[0]))}return e}function a(t){if(i[t])return i[t].exports;var r=i[t]={i:t,l:!1,exports:{}};return e[t].call(r.exports,r,r.exports,a),r.l=!0,r.exports}var i={},n={14:0},o=[];a.m=e,a.c=i,a.d=function(e,t,r){a.o(e,t)||Object.defineProperty(e,t,{enumerable:!0,get:r})},a.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},a.t=function(e,t){if(1&t&&(e=a(e)),8&t)return e;if(4&t&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(a.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&t&&"string"!=typeof e)for(var i in e)a.d(r,i,function(t){return e[t]}.bind(null,i));return r},a.n=function(e){var t=e&&e.__esModule?function(){return e.default}:function(){return e};return a.d(t,"a",t),t},a.o=function(e,t){return Object.prototype.hasOwnProperty.call(e,t)},a.p="";var p=window.webpackJsonp=window.webpackJsonp||[],d=p.push.bind(p);p.push=t,p=p.slice();for(var m=0;m<p.length;m++)t(p[m]);var c=d;o.push([122,0]),r()}({122:function(e,t,r){"use strict";r.r(t);var a=r(0);Object(a.a)("de","army",r(123),r(1))},123:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"半履带装甲车辆","link":"de_army#de_army_avhtv"}],"model":"251/16型半履带装甲喷火车","description":"<p>早期的东线苏联战场上，德军通过2号喷火坦克的实战，认为喷火装备有较强的杀伤力和摧毁力，于是决定继续发展机动喷火装备，并在1942年底开始用251的C型和D型车体改装半履带装甲喷火车，并定名为Sdkfz 251/16。德军在该型车的车厢内安装了一套火焰喷射系统（含喷火器、油泵、发动机和油箱），单枪可发射的火焰距离可达50～60米，能摧毁有较强防御能力的地下工事与坚固设施，对作战群体也有较大的杀伤力。</p><p>Sdkfz 251/16半履带装甲喷火车在1943年初开始正式装备部队，到1944年9月，德军用C、D型车体改装了近400辆。这些喷火车一直到二战结束，都是德军在战场上作近距攻坚的得力装备，但由于车上装有燃料，所以一旦被击中则容易燃烧或爆炸，所以在战场上被击毁的机率也是相当大的。</p>","part1title":"","part1description":"","part1content":[{"image":"{{text}}用251 C型车体改装的Sdkfz 251/16 Ausf C半履带装甲喷火车{{image}}imgs/de/army/de_army_avhtv25116_11.jpg{{text}}用251 D型车体改装的Sdkfz 251/16 Ausf D半履带装甲喷火车（注意：D型车的车厢后部已取消了7mm喷火枪）{{image}}imgs/de/army/de_army_avhtv25116_12.jpg","description":"<h6>Sdkfz 251/16型半履带装甲喷火车</h6><p>Sdkfz 251/16半履带装甲喷火车战斗全重8.62吨，核准载员4人，含1名驾驶员，1名车长(兼通讯员与前置机枪手）和2名喷火枪射手；车上除安装有喷火系统外，还会配备1挺前置MG34或MG42机枪和1挺后置高射机枪；车内有1部通讯电台，车外也会装有一根2米天线。</p><p>车上的喷火系统包括2支安置在车厢前部左右两侧带防盾的14mm口径火焰喷射器和一支安置在车厢后侧的7mm喷火枪（早期安装，后期取消），放置在车厢内有一容量为700升装有易燃液体油料的油箱，以及油泵和驱动油泵的发动机；当油泵发动时，单支14mm火焰喷射器的射程可达50～60米，在油箱满载时，可保证80次喷射（每次1分钟）。</p>","caption":""}],"part2title":"战场上的251/16型半履带装甲喷火车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_avhtv25116_21.jpg","description":"1943年春天，东线苏联战场，一辆隶属德军第16装甲师、采用251 C型车体改装的Sdkfz 251/16 Ausf C半履带装甲喷火车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25116_22.jpg","description":"1944年8月，东线战场波兰地区，一辆隶属德国武装党卫军第5“维京”装甲师、采用251 D型车体改装的Sdkfz 251/16 Ausf D半履带装甲喷火车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25116_23.jpg","description":"1944年6月，法国诺曼底战场，一辆隶属德国武装党卫军第2“帝国”装甲师、采用251 C型车体改装的Sdkfz 251/16 Ausf C半履带装甲喷火车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25116_24.jpg","description":"1945年5月德国，一辆隶属德国第19装甲师第73装甲炮兵团、采用251 D型车体改装的Sdkfz 251/16 Ausf D半履带装甲喷火车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25116_25.jpg","description":"一辆行进中的Sdkfz 251/16 Ausf C半履带装甲喷火车，图中可见车厢前方左右两支14mm火焰喷射器并不是并列安装，而是呈错开位置的，车后还挂着一支7mm喷火枪。","caption":""},{"image":"imgs/de/army/de_army_avhtv25116_26.jpg","description":"图片前方是一辆德军的Sdkfz 251/16半履带装甲喷火车在东线苏联战场上作战的情况，从模糊的身影中可看出该喷火车的两支火焰喷射器正在左右喷火（两支喷火器同时喷火时，火焰射程会减少为30～35米）。另外，图片中架有一挺MG42重机枪的是251/1装甲运兵车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25116_27.jpg","description":"一辆德军Sdkfz 251/16 Ausf C半履带装甲喷火车的14mm火焰喷射器正在发射喷火，图中可见操纵喷火器的士兵仍然穿着普通的军装，并没有按规定穿上防火服。","caption":""},{"image":"imgs/de/army/de_army_avhtv25116_28.jpg","description":"一辆德军Sdkfz 251/16 Ausf C半履带装甲喷火车的喷火器操纵士兵正在防盾内击发喷火器，两支14mm火焰喷射器一齐发射，火焰基本可将前方30米左右的目标完全复盖。","caption":""},{"image":"imgs/de/army/de_army_avhtv25116_29.jpg","description":"这是在战场上被击毁的一辆德军Sdkfz 251/16 Ausf C半履带装甲喷火车，所幸未击中车厢内燃油喷火系统，否则车子会燃烧爆炸，车上人员也会尸骨全无。","caption":""},{"image":"imgs/de/army/de_army_avhtv25116_30.jpg","description":"这是穿着防火服的德军Sdkfz 251/16半履带装甲喷火车上的喷火器操纵手与机枪射手。按德军规定，要求喷火车内乘员在战斗时要穿上防火服，但因为穿上防火服行动有些不便，所以在实战中会多数不穿。","caption":""},{"image":"imgs/de/army/de_army_avhtv25116_31.jpg","description":"这是一辆二战末期德军的一辆Sdkfz 251/16半履带装甲喷火车，但车上已安装了大功率电台的框形天线，可见该喷火车已改装为通讯车，原车内部的喷火装置应已拆除，虽然仍保留有前置的火焰喷射器，但是已不起作用。","caption":""}]}')}});